// A core made by `origami_core_new`, for programs without the control plane.
// C sees it as `origami_core` (see cbindgen.toml); the Rust name avoids the
// crate of that name.
typedef struct origami_core origami_core;

// The cube view: one cube drawn into one window. Opaque to C.
typedef struct origami_cube origami_cube;

// A machine as the frame plane sees it. Opaque to C.
typedef struct origami_machine origami_machine;

// The view: one head of one machine drawn into one window. Opaque to C.
typedef struct origami_view origami_view;

// What a frame-plane call returns: `ORIGAMI_OK` (zero) or a negative
// `ORIGAMI_ERR_*` code.
typedef int32_t origami_status;

// Where to draw. Fields by `kind`:
// COCOA_VIEW: `window` is the `NSView*`.
// CA_METAL_LAYER: `window` is the `CAMetalLayer*`.
// WIN32_HWND: `window` is the `HWND`.
// XLIB_WINDOW: `window_id` is the `Window`, `display` the `Display*`,
// `screen` the screen number.
// XCB_WINDOW: `window_id` is the `xcb_window_t`, `display` the
// `xcb_connection_t*`, `screen` the screen number.
// WAYLAND_SURFACE: `window` is the `wl_surface*`, `display` the `wl_display*`.
// The caller sets `size` to `sizeof(origami_surface)`.
typedef struct origami_surface {
  uint32_t size;
  uint32_t kind;
  void *window;
  void *display;
  uint64_t window_id;
  int32_t screen;
} origami_surface;

// How the cube looks and moves. Colours are `0xRRGGBB`; the caller sets
// `size` to `sizeof(origami_cube_style)`.
// - `env`: `ORIGAMI_CUBE_ENV_*`. The machine's screen shows the studio until
//   its first picture has been copied.
// - `scene`: for `ORIGAMI_CUBE_ENV_SCENE`, an index below
//   `origami_cube_scene_count`; `origami_cube_scene_for_time` gives About's.
// - `horizon_rgb`: the studio's horizon band colour (a machine's chassis
//   colour on the start screen), or `ORIGAMI_CUBE_NO_COLOUR`.
// - `granite_light_rgb`, `granite_dark_rgb`: the backdrop tile's two tones.
// - `light_look`: the lighter chrome studio, for a light window.
// - `spin`: turn at 10 rpm; without it the cube is at rest until dragged.
// - `reduce_motion`: draw the still pose and never spin; a drag still turns
//   it and it stops dead on release.
// - `backdrop`: `_NONE` leaves the view transparent around the cube, over the
//   host's own (non-opaque) surface; `_GRANITE` draws the tile. `surround_rgb`
//   fills the view where the window system gives no alpha. A smaller `size`
//   (a host built before these fields) means granite.
typedef struct origami_cube_style {
  uint32_t size;
  uint32_t env;
  uint32_t scene;
  uint32_t horizon_rgb;
  uint32_t granite_light_rgb;
  uint32_t granite_dark_rgb;
  uint32_t light_look;
  uint32_t spin;
  uint32_t reduce_motion;
  uint32_t backdrop;
  uint32_t surround_rgb;
} origami_cube_style;

// What a view has spent, in wall nanoseconds, since it was attached.
typedef struct origami_view_counters {
  uint32_t size;
  uint32_t reserved;
  // Pictures drawn and presented.
  uint64_t presents;
  // Taking the frame from the display client and updating the cursor.
  uint64_t take_ns;
  // Acquiring the window's image, drawing the picture and the head into it.
  uint64_t draw_ns;
  // Handing the image to the window system, which can make it large.
  uint64_t present_ns;
} origami_view_counters;

typedef struct origami_head_info {
  uint32_t width;
  uint32_t height;
  uint64_t seq;
  // 0 while the head has no picture.
  uint32_t active;
  uint32_t reserved;
} origami_head_info;

// One run of changed lines, `y0` up to but not including `y1`.
typedef struct origami_run {
  uint32_t y0;
  uint32_t y1;
} origami_run;

// What `origami_frame_take` found. The caller sets `size` to
// `sizeof(origami_frame)`.
typedef struct origami_frame {
  uint32_t size;
  // `ORIGAMI_FRAME_NONE` or `ORIGAMI_FRAME_ROWS`.
  uint32_t kind;
  uint64_t seq;
  uint32_t width;
  uint32_t height;
  // The head changed size: the whole picture is new.
  uint32_t resized;
  // Runs written to the caller's array.
  uint32_t run_count;
  // Bytes written to the pixel buffer: the changed rows one after another,
  // 4 bytes a pixel (blue, green, red, unused), tight. With
  // `BufferTooSmall`, the bytes needed.
  uint64_t bytes_used;
} origami_frame;

// What the display client has moved since the machine started.
typedef struct origami_frame_counters {
  uint32_t size;
  // 0 when the engine does not count; the rest is then zero.
  uint32_t counted;
  uint64_t frames;
  // Lines handed out, copied or imported.
  uint64_t lines;
  // Lines the GPU reads in place, a part of `lines`.
  uint64_t imported_lines;
  // Pixel bytes copied by the CPU: 0 when every picture is imported.
  uint64_t copied_bytes;
} origami_frame_counters;

// The guest's cursor on a head.
typedef struct origami_cursor {
  uint32_t size;
  // 0 when the engine draws the cursor into the picture; the rest is then
  // zero.
  uint32_t present;
  uint32_t on;
  int32_t x;
  int32_t y;
  int32_t hot_x;
  int32_t hot_y;
  uint32_t width;
  uint32_t height;
  // Moves when the image changes.
  uint32_t gen;
  // Bytes of image written, 0 when `gen` is the one the caller passed.
  // With `BufferTooSmall`, the bytes needed.
  uint32_t image_bytes;
} origami_cursor;

// Called on an engine thread when a head has a new picture. Do almost
// nothing and never block: set a flag or post to your UI thread.
typedef void (*origami_wake_fn)(void *user_data);

// One input event. Fields by `kind`:
// KEY: `code` is an `origami_key`, `down`.
// POINTER_MOVE: `x`, `y` are relative guest counts.
// POINTER_AT: `head`, `x`, `y` in the head's pixels.
// BUTTON: `code` is `ORIGAMI_BUTTON_*`, `down`.
// WHEEL: `x` is notches, positive away from the user.
typedef struct origami_input_event {
  uint32_t kind;
  uint32_t code;
  uint32_t down;
  uint32_t head;
  int32_t x;
  int32_t y;
} origami_input_event;

// Where the picture is drawn, in window physical pixels; guest x is
// `(window x - x) / scale`.
typedef struct origami_view_layout {
  uint32_t size;
  uint32_t reserved;
  double x;
  double y;
  double width;
  double height;
  // Physical pixels per guest pixel.
  double scale;
} origami_view_layout;

#define ORIGAMI_OK 0

#define ORIGAMI_ERR_NULL_ARGUMENT -1

#define ORIGAMI_ERR_INVALID_ARGUMENT -2

#define ORIGAMI_ERR_NOT_RUNNING -3

// A buffer was too small; the call says what size it needed and nothing
// was lost. Call again for the same head with a bigger buffer.
#define ORIGAMI_ERR_BUFFER_TOO_SMALL -4

#define ORIGAMI_ERR_UNSUPPORTED -5

#define ORIGAMI_ERR_NO_GPU -6

#define ORIGAMI_ERR_PANIC -7

#define ORIGAMI_ERR_ENGINE -8

#define ORIGAMI_ERR_NOT_FOUND -9

#define ORIGAMI_ERR_BUSY -10

#define ORIGAMI_ERR_IO -11

#define ORIGAMI_ERR_INTERNAL -12

